package com.tripnest.entity; import jakarta.persistence.*; @Entity @Table(name="accommodation_images") public class AccommodationImage { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false) String url; @Column(name="sort_order") int sortOrder; public Long getId(){return id;} public String getUrl(){return url;} public void setUrl(String v){url=v;} public int getSortOrder(){return sortOrder;} public void setSortOrder(int v){sortOrder=v;} }
